<?php $base='../';require_once '../config/config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];$allowed=['Pending','Reviewed','Quotation Sent','Approved','In Progress','Completed','Rejected'];if(in_array($status,$allowed)){db()->prepare('UPDATE service_requests SET status=? WHERE request_id=?')->execute([$status,$id]);$q=db()->prepare('SELECT customer_id FROM service_requests WHERE request_id=?');$q->execute([$id]);$uid=$q->fetchColumn();db()->prepare('INSERT INTO notifications(user_id,message) VALUES(?,?)')->execute([$uid,'Your service request status changed to '.$status.'.']);flash('success','Request updated.');}header('Location: requests.php');exit;}$rows=db()->query('SELECT r.*,u.full_name,u.email,s.service_name FROM service_requests r JOIN users u ON u.user_id=r.customer_id JOIN services s ON s.service_id=r.service_id ORDER BY r.created_at DESC')->fetchAll();$title='Manage Requests';include '../includes/header.php';?><section class="section"><div class="container"><h1>Service Requests</h1><?php show_flash();?><div class="table-responsive mt-4"><table class="table table-dark align-middle"><thead><tr><th>ID</th><th>Customer</th><th>Service</th><th>Project</th><th>Date</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=$r['request_id']?></td><td><?=e($r['full_name'])?></td><td><?=e($r['service_name'])?></td><td><?=e($r['project_title'])?></td><td><?=e($r['preferred_date'])?></td><td><span class="badge badge-gold"><?=e($r['status'])?></span></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['request_id']?>"><select name="status" class="form-select form-select-sm"><?php foreach(['Pending','Reviewed','Quotation Sent','Approved','In Progress','Completed','Rejected'] as $s):?><option <?= $r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-sm btn-gold">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div></section><?php include '../includes/footer.php';?>
